def note(dimension, metric, judgment, evidence, limitation, origin="new_draft"):
    return dict(chosen_dimension=dimension, primary_metric=metric,
                alignment_judgment=judgment, evidence_note=evidence,
                limitation_note=limitation, draft_origin=origin)


